import {pointAt} from './mall-plans.js?v=23.0.0';
export function projectSegment(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1)));return {x:a.x+t*dx,y:a.y+t*dy,t,distance:Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy)};}
export function projectToMap(p,plan){return plan.edges.map(edge=>({...projectSegment(p,pointAt(plan,edge.a),pointAt(plan,edge.b)),edge})).sort((a,b)=>a.distance-b.distance)[0];}
export const onCorridor=(p,plan)=>{const nearest=projectToMap(p,plan);return !!nearest&&nearest.distance<=nearest.edge.width/2-5;};
export function moveOnMap(from,to,plan){if(onCorridor(to,plan))return to;const p=projectToMap(to,plan);const max=p.edge.width/2-6,dx=to.x-p.x,dy=to.y-p.y,d=Math.hypot(dx,dy)||1,candidate={x:p.x+dx/d*max,y:p.y+dy/d*max};return Math.hypot(candidate.x-from.x,candidate.y-from.y)<=Math.hypot(to.x-from.x,to.y-from.y)+2?candidate:from;}
export function mapRoute(start,end,plan){const a=projectToMap(start,plan),b=projectToMap(end,plan);if(!a||!b)return [];const nodes=new Map(plan.nodes.map(n=>[n.id,{...n}]));nodes.set('@start',{id:'@start',x:a.x,y:a.y});nodes.set('@end',{id:'@end',x:b.x,y:b.y});const links=new Map([...nodes.keys()].map(id=>[id,[]]));const add=(x,y)=>{const p=nodes.get(x),q=nodes.get(y),d=Math.hypot(p.x-q.x,p.y-q.y);links.get(x).push([y,d]);links.get(y).push([x,d]);};for(const e of plan.edges)add(e.a,e.b);for(const id of [a.edge.a,a.edge.b])add('@start',id);for(const id of [b.edge.a,b.edge.b])add('@end',id);if(a.edge===b.edge)add('@start','@end');const dist=new Map([['@start',0]]),prev=new Map(),open=new Set(nodes.keys());while(open.size){let cur=[...open].reduce((p,q)=>(dist.get(p)??Infinity)<(dist.get(q)??Infinity)?p:q);if(!Number.isFinite(dist.get(cur)))return [];open.delete(cur);if(cur==='@end'){const ids=[cur];while(prev.has(cur)){cur=prev.get(cur);ids.unshift(cur);}return [{x:start.x,y:start.y},...ids.map(id=>({x:nodes.get(id).x,y:nodes.get(id).y}))];}for(const [next,weight] of links.get(cur)){const cost=dist.get(cur)+weight;if(cost<(dist.get(next)??Infinity)){dist.set(next,cost);prev.set(next,cur);}}}return [];}
